import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Chat integrations","description":"","frontmatter":{},"headers":[],"relativePath":"chat.md","filePath":"chat.md","lastUpdated":1793870103000}'),n={name:"chat.md"};function o(r,s,h,l,d,p){return t(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="chat-integrations" tabindex="-1">Chat integrations <a class="header-anchor" href="#chat-integrations" aria-label="Permalink to &quot;Chat integrations&quot;">​</a></h1><p>Telegram and Signal notify you when a session waits for input or finishes, and let you reply, approve permission prompts and start new sessions from your phone. Both are part of the free core — <a href="/docs/slack">Slack</a> is an Enterprise feature.</p><p>A session shows up in chat only after one of its hooks reports that it is waiting for input. That happens in <strong>interactive</strong> Claude, Codex, Cursor and OpenCode sessions. Autonomous and scheduled sessions do not wait for input, so they never open a conversation on their own. The exception is a session you started from the chat with <code>/new</code>. <strong>OpenClaw sessions never show up in chat</strong> because OpenClaw has no hook for it. Cursor sessions show up, but their permission prompts are not sent to chat: Cursor decides approvals from its own allowlist.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> the operator enables the bots; each user links their own chat.</p><p>Long answers are split across several messages. Permission prompts expire after about 30 minutes; after that, answer in the web terminal.</p><h2 id="one-replica-only" tabindex="-1">One replica only <a class="header-anchor" href="#one-replica-only" aria-label="Permalink to &quot;One replica only {#one-replica-only}&quot;">​</a></h2><p>Both integrations require <code>backend.replicas=1</code>. Telegram&#39;s <code>getUpdates</code> and the Signal receive socket each allow exactly one consumer, and a second poller would fight the first for every update. The chart refuses to render otherwise:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: chat.telegram/chat.signal require backend.replicas=1</span></span></code></pre></div><p>The backend default is <strong>2</strong>, so enabling chat halves it. That is a real availability trade-off: no failover, and a brief gap during rolling updates. Nothing is lost when the pod restarts — Telegram buffers updates by offset for roughly 24 hours.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><h3 id="_1-create-the-bot" tabindex="-1">1. Create the bot <a class="header-anchor" href="#_1-create-the-bot" aria-label="Permalink to &quot;1. Create the bot&quot;">​</a></h3><p>Talk to <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a>, create a bot, and copy the token. It looks like <code>123456789:AAF…</code>.</p><h3 id="_2-enable-it" tabindex="-1">2. Enable it <a class="header-anchor" href="#_2-enable-it" aria-label="Permalink to &quot;2. Enable it&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.botToken=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend.replicas=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>Use <code>--set-string</code> for the token: it contains a colon, and <code>--set</code> would try to be clever about it.</p><p>Without Helm, the equivalent environment variables are <code>Chat__Telegram__Enabled=true</code> and <code>Chat__Telegram__BotToken=&lt;token&gt;</code>.</p><h3 id="verify-telegram" tabindex="-1">3. Verify it works <a class="header-anchor" href="#verify-telegram" aria-label="Permalink to &quot;3. Verify it works {#verify-telegram}&quot;">​</a></h3><p>The backend is quiet on success, so &quot;no errors in the log&quot; is the expected state and not much of a signal. Ask Telegram instead — the backend publishes the bot&#39;s command menu at startup, so if the commands are registered, the connection works end to end:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.telegram.org/bot&lt;token&gt;/getMyCommands&quot;</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Link this chat to your AgentHub account&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Start a new session: /new [+repo] &lt;prompt&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;repos&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;List your GitHub/GitLab projects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sessions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;List sessions in this chat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;use&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Choose the session for plain replies; it stays chosen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unpin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Plain replies follow the newest session again&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Show session status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>An empty <code>result</code> means the backend never reached Telegram. Check the log for the giveaway line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/agenthub-backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span></code></pre></div><p><code>Telegram long polling not started (no bot token / disabled)</code> means the configuration did not arrive. A <code>Conflict: terminated by other getUpdates request</code> warning means two pollers are running — expected for a few seconds during a rolling update, a problem if it persists (check <code>backend.replicas</code>).</p><h3 id="_4-link-your-account" tabindex="-1">4. Link your account <a class="header-anchor" href="#_4-link-your-account" aria-label="Permalink to &quot;4. Link your account&quot;">​</a></h3><p>Each user links themselves: <strong>Settings → Notifications → Telegram notifications → Generate link code</strong>, then click <strong>Open in Telegram</strong>, or send <code>/link &lt;code&gt;</code> to the bot directly. The code expires after 10 minutes.</p><h3 id="per-session-forum-topics" tabindex="-1">Per-session forum topics <a class="header-anchor" href="#per-session-forum-topics" aria-label="Permalink to &quot;Per-session forum topics&quot;">​</a></h3><p>Optional, and worth it if you run several sessions at once. Create a Telegram group, turn on <strong>Topics</strong>, add the bot as an admin with the <strong>Manage topics</strong> permission, and send <code>/link &lt;code&gt;</code> in the group. Every session then gets its own topic.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Everyone in a linked group can reply to sessions and approve permission prompts. A <code>/use</code> choice applies to the whole group, not only to the person who sent it.</p></div><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><p>Each chat message names its session as <code>Name (#ab12)</code>. The <code>#ab12</code> part is the session&#39;s tag: the first characters of its id.</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>/link &lt;code&gt;</code></td><td>Link this chat to your account</td></tr><tr><td><code>/new [+repo …] &lt;prompt&gt;</code></td><td>Start a new autonomous Claude session that works on the prompt. Leading <code>+name</code>, <code>+group/name</code>, <code>+name#branch</code> or <code>+https://…</code> tokens attach repositories.</td></tr><tr><td><code>/repos [query]</code></td><td>List the projects of your connected GitHub/GitLab accounts</td></tr><tr><td><code>/sessions</code></td><td>List this chat&#39;s sessions, most recent activity first, at most 15</td></tr><tr><td><code>/use #ab12</code></td><td>Send plain replies to that session until you choose another. Works with or without <code>#</code>, any letter case.</td></tr><tr><td><code>/unpin</code> or <code>/use auto</code></td><td>Plain replies follow the newest session again</td></tr><tr><td><code>/status</code></td><td>Show the session&#39;s status, pending permission and link</td></tr></tbody></table><p>Telegram accepts every command except <code>/link</code> with a <code>!</code> prefix as well, so <code>!status</code> and <code>/status</code> do the same thing.</p><h3 id="which-session-a-message-goes-to" tabindex="-1">Which session a message goes to <a class="header-anchor" href="#which-session-a-message-goes-to" aria-label="Permalink to &quot;Which session a message goes to&quot;">​</a></h3><p>Plain messages are typed into a session&#39;s terminal. The session is chosen in this order:</p><ol><li>In a forum group, the session whose topic the message is in.</li><li>The session of the message you reply to.</li><li>The session you chose with <code>/use</code>.</li><li>Otherwise, the session that posted most recently.</li></ol><p><code>/use</code> keeps its choice even when other sessions post. <code>/new</code> moves an existing <code>/use</code> choice to the session it just started.</p><h3 id="deleted-sessions" tabindex="-1">Deleted sessions <a class="header-anchor" href="#deleted-sessions" aria-label="Permalink to &quot;Deleted sessions&quot;">​</a></h3><p>When a session is deleted, its chat links are removed. A message meant for it gets a reply saying it was deleted, with a pointer to <code>/sessions</code> and <code>/use</code>. In a forum group its topic stays as history. If the deleted session was the one you chose with <code>/use</code>, the message is not sent to another session: choose a new one, or <code>/unpin</code>.</p><h2 id="signal" tabindex="-1">Signal <a class="header-anchor" href="#signal" aria-label="Permalink to &quot;Signal&quot;">​</a></h2><h3 id="_1-enable-it" tabindex="-1">1. Enable it <a class="header-anchor" href="#_1-enable-it" aria-label="Permalink to &quot;1. Enable it&quot;">​</a></h3><p>This deploys <a href="https://github.com/bbernhard/signal-cli-rest-api" target="_blank" rel="noreferrer">signal-cli-rest-api</a> with a persistent volume for the account keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.signal.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.signal.number=+15551234567</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend.replicas=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="_2-register-the-sender-number" tabindex="-1">2. Register the sender number <a class="header-anchor" href="#_2-register-the-sender-number" aria-label="Permalink to &quot;2. Register the sender number&quot;">​</a></h3><p>Once, via port-forward: <code>POST /v1/register/&lt;number&gt;</code> followed by <code>/v1/register/&lt;number&gt;/verify/&lt;token&gt;</code> with the SMS or voice code. You can also link it as a secondary device by QR code. The exact commands are in the comment block of <a href="https://github.com/open-agenthub/open-agenthub/blob/main/helm/open-agenthub/templates/signal-cli.yaml" target="_blank" rel="noreferrer"><code>templates/signal-cli.yaml</code></a>.</p><p>The image tag is pinned on purpose — the account registration and keys live on the PVC, so check the signal-cli-rest-api release notes for migration steps before bumping it.</p><h3 id="_3-link-your-account" tabindex="-1">3. Link your account <a class="header-anchor" href="#_3-link-your-account" aria-label="Permalink to &quot;3. Link your account&quot;">​</a></h3><p>Each user enters their number under <strong>Settings → Notifications → Signal</strong> and confirms the six-digit code sent via Signal.</p><h3 id="reply-routing" tabindex="-1">Reply routing <a class="header-anchor" href="#reply-routing" aria-label="Permalink to &quot;Reply routing&quot;">​</a></h3><p><strong>Quote</strong> a session message to answer that session. Unquoted messages go to the session you chose with <code>!use</code>, or else to the session that posted most recently. React 👍/👎 on a permission prompt to allow or deny, and quote-reply <code>always</code> for allow-always.</p><p>Signal accepts commands with the <code>!</code> prefix only:</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>!new [+repo …] &lt;prompt&gt;</code></td><td>Start a new autonomous Claude session. Leading <code>+name</code> tokens attach repositories.</td></tr><tr><td><code>!repos [query]</code></td><td>List your GitHub/GitLab projects</td></tr><tr><td><code>!sessions</code></td><td>List your sessions, most recent activity first, at most 15</td></tr><tr><td><code>!use #ab12</code></td><td>Send unquoted messages to that session until you choose another</td></tr><tr><td><code>!unpin</code> or <code>!use auto</code></td><td>Follow the newest session again</td></tr><tr><td><code>!status</code></td><td>Show the session&#39;s status</td></tr></tbody></table><p>Deleted sessions work as they do on Telegram.</p><p>Not tested: delivery through a real Telegram or Signal account. These features were tested against a recorded stand-in of the Telegram Bot API, and Signal&#39;s <code>!use</code> only in unit tests.</p><h2 id="desktop-notifications" tabindex="-1">Desktop notifications <a class="header-anchor" href="#desktop-notifications" aria-label="Permalink to &quot;Desktop notifications&quot;">​</a></h2><p>A browser notification when a session waits for input or finishes. Enable it per device under <strong>Settings → Notifications</strong> — no cluster configuration needed.</p><h2 id="values-masked-in-session-output" tabindex="-1">Values masked in session output <a class="header-anchor" href="#values-masked-in-session-output" aria-label="Permalink to &quot;Values masked in session output&quot;">​</a></h2><p>Masking is automatic; session owners do not need to enable it. Before a session&#39;s hook message is sent to a chat integration, AgentHub replaces the session&#39;s file and environment secrets, its callback token, and credential values in its inline MCP configuration. This includes custom header and environment values, authorization tokens, complete URLs, and URL usernames, passwords and query values in their encoded and decoded forms. The replacement appears as <code>[secret:NAME]</code>, <code>[secret:AGENTHUB_CALLBACK_TOKEN]</code> or <code>[secret:MCP]</code>.</p><p>The same values are masked in transcript and scrollback uploads, live conversation history and terminal reconnect replay. Commands and arguments remain readable. Owners and collaborators with terminal access still see the normal live terminal and their own input echo. Shared conversation history also masks these credentials, using <code>[redacted]</code>.</p><p>Values shorter than eight characters are left unchanged to keep ordinary output readable. Masking matches literal values, their JSON-escaped form and long enough individual lines; it does not cover arbitrary transformations or other encodings. Existing stored transcripts are not rewritten. Keep credentials out of prompts and output where possible.</p><p>This behavior is included in the free core for the session runtime, Telegram and Signal hooks. Slack hooks and shared session history require Enterprise. The same rules apply regardless of who reads the delivered history; terminal access still follows the session&#39;s role permissions.</p>`,60)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
